contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public {
        require(recipient != address(0));
        require(recipient != address(c));
        require(recipient != address(this));

        uint256 cBefore = address(c).balance;
        uint256 recipBefore = recipient.balance;

        bool reverted;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 cAfter = address(c).balance;
        uint256 recipAfter = recipient.balance;

        assert(reverted ? (recipAfter == recipBefore && cAfter == cBefore) : (recipAfter == recipBefore + 100 && cAfter == cBefore - 100));
    }

    receive() external payable {}
}

